static inline void protection_write(uint32_t offset, uint32_t value)
{
    volatile uint32_t *addr =
        (volatile uint32_t *)(uintptr_t)(PROTECTION_IP_BASEADDR + offset);
    *addr = value;
}

static inline uint32_t protection_read(uint32_t offset)
{
    volatile uint32_t *addr =
        (volatile uint32_t *)(uintptr_t)(PROTECTION_IP_BASEADDR + offset);
    return *addr;
}

